'use client';

import React from 'react';
import { Rect, Group, Line, Circle } from 'react-konva';
import { BaseElement } from './BaseElement';
import { CanvasElement, BackgroundElementData } from '@/types/canvas-elements';

interface BackgroundElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

/**
 * BackgroundElement - Renders backgrounds in the canvas editor
 *
 * Features:
 * - Solid background
 * - Gradient background (linear)
 * - Pattern background (dots, stripes, grid)
 * - Geometric background (circles, squares, triangles)
 * - Advanced backgrounds:
 *   - glass-gradient
 *   - cyber-grid
 *   - gradient-mesh
 *   - isometric-grid
 *   - holographic
 *   - vaporwave
 *   - scanlines
 *   - noise
 * - Background effects (shadow, glow, blur, noise)
 * - Opacity support
 * - Blend mode support
 */
export const BackgroundElement: React.FC<BackgroundElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  const bgData = element.data as BackgroundElementData;

  // Calculate gradient stops based on angle
  const gradientStops = React.useMemo(() => {
    if (bgData.backgroundType !== 'gradient' && bgData.backgroundType !== 'glass-gradient') {
      return [];
    }

    const angle = bgData.gradientAngle || 90;
    const primary = bgData.primaryColor || '#000000';
    const secondary = bgData.secondaryColor || '#00E5FF';

    // Calculate gradient direction based on angle
    const getGradientCoords = (angle: number) => {
      const rad = (angle * Math.PI) / 180;
      const x1 = 50 + 50 * Math.cos(rad);
      const y1 = 50 + 50 * Math.sin(rad);
      const x2 = 50 - 50 * Math.cos(rad);
      const y2 = 50 - 50 * Math.sin(rad);
      return `${x1}% ${y1}%, ${x2}% ${y2}%`;
    };

    return [
      0, getGradientCoords(angle), primary,
      1, getGradientCoords(angle + 180), secondary,
    ];
  }, [bgData.backgroundType, bgData.primaryColor, bgData.secondaryColor, bgData.gradientAngle]);

  // Calculate pattern scale
  const patternScale = bgData.patternScale || 20;

  // Render solid background
  const renderSolid = () => (
    <Rect
      x={0}
      y={0}
      width={element.width}
      height={element.height}
      fill={bgData.primaryColor}
      opacity={bgData.opacity}
      globalCompositeOperation={bgData.blendMode || 'source-over'}
      perfectDrawEnabled={false}
    />
  );

  // Render gradient background
  const renderGradient = () => (
    <Rect
      x={0}
      y={0}
      width={element.width}
      height={element.height}
      fillLinearGradientStartPoint={{ x: 0, y: 0 }}
      fillLinearGradientEndPoint={{ x: element.width, y: element.height }}
      fillLinearGradientColorStops={gradientStops}
      opacity={bgData.opacity}
      globalCompositeOperation={bgData.blendMode || 'source-over'}
      perfectDrawEnabled={false}
    />
  );

  // Render pattern background - dots
  const renderDotsPattern = () => {
    const dotSize = patternScale / 4;
    const spacing = patternScale;
    const cols = Math.ceil(element.width / spacing);
    const rows = Math.ceil(element.height / spacing);

    return (
      <Group>
        {/* Base color */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Dots */}
        {Array.from({ length: rows }).map((_, rowIndex) =>
          Array.from({ length: cols }).map((_, colIndex) => (
            <Circle
              key={`${rowIndex}-${colIndex}`}
              x={colIndex * spacing + spacing / 2}
              y={rowIndex * spacing + spacing / 2}
              radius={dotSize / 2}
              fill={bgData.secondaryColor || '#00E5FF'}
              opacity={bgData.opacity * 0.5}
              globalCompositeOperation={bgData.blendMode || 'source-over'}
            />
          ))
        )}
      </Group>
    );
  };

  // Render pattern background - stripes
  const renderStripesPattern = () => {
    const stripeWidth = patternScale / 2;
    const spacing = patternScale;
    const stripes = Math.ceil(element.height / spacing);

    return (
      <Group>
        {/* Base color */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Stripes */}
        {Array.from({ length: stripes }).map((_, index) => (
          <Rect
            key={index}
            x={0}
            y={index * spacing}
            width={element.width}
            height={stripeWidth}
            fill={bgData.secondaryColor || '#00E5FF'}
            opacity={bgData.opacity * 0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
            perfectDrawEnabled={false}
          />
        ))}
      </Group>
    );
  };

  // Render pattern background - grid
  const renderGridPattern = () => {
    const lineWidth = patternScale / 10;
    const spacing = patternScale;
    const cols = Math.ceil(element.width / spacing);
    const rows = Math.ceil(element.height / spacing);

    return (
      <Group>
        {/* Base color */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Vertical lines */}
        {Array.from({ length: cols }).map((_, index) => (
          <Line
            key={`v-${index}`}
            x={index * spacing}
            y={0}
            width={lineWidth}
            height={element.height}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={lineWidth}
            opacity={bgData.opacity * 0.5}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
        {/* Horizontal lines */}
        {Array.from({ length: rows }).map((_, index) => (
          <Line
            key={`h-${index}`}
            x={0}
            y={index * spacing}
            width={element.width}
            height={lineWidth}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={lineWidth}
            opacity={bgData.opacity * 0.5}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
      </Group>
    );
  };

  // Render geometric background - circles
  const renderCircles = () => {
    const circles: { cx: number; cy: number; radius: number }[] = [];
    const cols = 5;
    const rows = 6;
    const spacingX = element.width / cols;
    const spacingY = element.height / rows;
    const maxRadius = spacingY * 0.4;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        circles.push({
          cx: col * spacingX + spacingX / 2,
          cy: row * spacingY + spacingY / 2,
          radius: Math.random() * maxRadius,
        });
      }
    }

    return (
      <Group>
        {/* Base color */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Circles */}
        {circles.map((circle, index) => (
          <Circle
            key={index}
            cx={circle.cx}
            cy={circle.cy}
            radius={circle.radius}
            fill={bgData.secondaryColor || '#00E5FF'}
            opacity={bgData.opacity * 0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
      </Group>
    );
  };

  // Render geometric background - squares
  const renderSquares = () => {
    const squares: { x: number; y: number; size: number; rotation: number }[] = [];
    const cols = 5;
    const rows = 6;
    const spacingX = element.width / cols;
    const spacingY = element.height / rows;
    const maxSize = spacingY * 0.35;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        squares.push({
          x: col * spacingX + spacingX / 2,
          y: row * spacingY + spacingY / 2,
          size: Math.random() * maxSize,
          rotation: Math.random() * 360,
        });
      }
    }

    return (
      <Group>
        {/* Base color */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Squares */}
        {squares.map((square, index) => (
          <Rect
            key={index}
            x={square.x}
            y={square.y}
            width={square.size}
            height={square.size}
            rotation={square.rotation}
            offsetX={square.size / 2}
            offsetY={square.size / 2}
            fill={bgData.secondaryColor || '#00E5FF'}
            opacity={bgData.opacity * 0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
            perfectDrawEnabled={false}
          />
        ))}
      </Group>
    );
  };

  // Render geometric background - triangles
  const renderTriangles = () => {
    const triangles: { points: number[] }[] = [];
    const cols = 4;
    const rows = 5;
    const spacingX = element.width / cols;
    const spacingY = element.height / rows;
    const maxSize = spacingY * 0.4;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const centerX = col * spacingX + spacingX / 2;
        const centerY = row * spacingY + spacingY / 2;
        const size = Math.random() * maxSize;

        // Create triangle points (equilateral)
        const height = size * Math.sqrt(3) / 2;
        const halfWidth = size / 2;

        triangles.push({
          points: [
            centerX, centerY - height / 2,
            centerX - halfWidth, centerY + height / 2,
            centerX + halfWidth, centerY + height / 2,
          ],
        });
      }
    }

    return (
      <Group>
        {/* Base color */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Triangles */}
        {triangles.map((triangle, index) => (
          <Line
            key={index}
            points={triangle.points}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={2}
            closed
            lineJoin="round"
            opacity={bgData.opacity * 0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
      </Group>
    );
  };

  // Render glass-gradient background
  const renderGlassGradient = () => {
    return (
      <Group>
        {/* Base gradient */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fillLinearGradientStartPoint={{ x: element.width * 0.3, y: element.height * 0.3 }}
          fillLinearGradientEndPoint={{ x: element.width * 0.7, y: element.height * 0.7 }}
          fillLinearGradientColorStops={[
            0, bgData.primaryColor,
            0.5, bgData.secondaryColor || '#00E5FF',
            1, bgData.primaryColor,
          ]}
          opacity={bgData.opacity * 0.6}
          globalCompositeOperation={bgData.blendMode || 'source-over'}
          perfectDrawEnabled={false}
        />
        {/* Glass reflection */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height * 0.4}
          fillLinearGradientStartPoint={{ x: 0, y: 0 }}
          fillLinearGradientEndPoint={{ x: element.width, y: element.height * 0.4 }}
          fillLinearGradientColorStops={[
            0, 'rgba(255, 255, 255, 0.3)',
            1, 'rgba(255, 255, 255, 0)',
          ]}
          opacity={0.5}
          globalCompositeOperation="overlay"
          perfectDrawEnabled={false}
        />
      </Group>
    );
  };

  // Render cyber-grid background
  const renderCyberGrid = () => {
    const gridSize = patternScale * 2;
    const cols = Math.ceil(element.width / gridSize);
    const rows = Math.ceil(element.height / gridSize);

    return (
      <Group>
        {/* Dark base */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity * 0.8}
          perfectDrawEnabled={false}
        />
        {/* Grid lines */}
        {Array.from({ length: cols }).map((_, index) => (
          <Line
            key={`v-${index}`}
            x={index * gridSize}
            y={0}
            width={1}
            height={element.height}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={1}
            opacity={0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
        {Array.from({ length: rows }).map((_, index) => (
          <Line
            key={`h-${index}`}
            x={0}
            y={index * gridSize}
            width={element.width}
            height={1}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={1}
            opacity={0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
        {/* Glowing nodes at intersections */}
        {Array.from({ length: cols }).map((_, colIndex) =>
          Array.from({ length: rows }).map((_, rowIndex) => (
            <Circle
              key={`node-${colIndex}-${rowIndex}`}
              x={colIndex * gridSize}
              y={rowIndex * gridSize}
              radius={2}
              fill={bgData.secondaryColor || '#00E5FF'}
              opacity={0.6}
              globalCompositeOperation="screen"
            />
          ))
        )}
      </Group>
    );
  };

  // Render gradient-mesh background
  const renderGradientMesh = () => {
    const meshSize = patternScale * 3;
    const cols = Math.ceil(element.width / meshSize) + 1;
    const rows = Math.ceil(element.height / meshSize) + 1;

    // Generate random gradient points
    const gradientPoints = Array.from({ length: cols * rows }).map((_, index) => {
      const col = index % cols;
      const row = Math.floor(index / cols);
      return {
        x: col * meshSize,
        y: row * meshSize,
        color: index % 2 === 0 ? bgData.primaryColor : (bgData.secondaryColor || '#00E5FF'),
      };
    });

    return (
      <Group>
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {gradientPoints.map((point, index) => (
          <Circle
            key={index}
            x={point.x}
            y={point.y}
            radius={meshSize * 0.8}
            fill={point.color}
            opacity={0.4}
            blur={meshSize * 0.5}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
      </Group>
    );
  };

  // Render isometric-grid background
  const renderIsometricGrid = () => {
    const gridSize = patternScale * 2;
    const cols = Math.ceil(element.width / gridSize) * 2;
    const rows = Math.ceil(element.height / gridSize);

    return (
      <Group>
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity * 0.7}
          perfectDrawEnabled={false}
        />
        {/* Isometric lines */}
        {Array.from({ length: cols }).map((_, index) => (
          <Line
            key={`iso1-${index}`}
            points={[
              index * gridSize * 0.5, 0,
              0, index * gridSize * 0.866,
            ]}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={1}
            opacity={0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
        {Array.from({ length: cols }).map((_, index) => (
          <Line
            key={`iso2-${index}`}
            points={[
              element.width - index * gridSize * 0.5, 0,
              element.width, index * gridSize * 0.866,
            ]}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={1}
            opacity={0.3}
            globalCompositeOperation={bgData.blendMode || 'source-over'}
          />
        ))}
      </Group>
    );
  };

  // Render holographic background
  const renderHolographic = () => {
    const bands = 20;
    const bandHeight = element.height / bands;

    return (
      <Group>
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity * 0.5}
          perfectDrawEnabled={false}
        />
        {Array.from({ length: bands }).map((_, index) => (
          <Rect
            key={index}
            x={0}
            y={index * bandHeight}
            width={element.width}
            height={bandHeight}
            fill={index % 2 === 0 ? bgData.secondaryColor : bgData.primaryColor}
            opacity={0.3}
            globalCompositeOperation="overlay"
            perfectDrawEnabled={false}
          />
        ))}
        {/* Holographic interference patterns */}
        {Array.from({ length: 5 }).map((_, index) => (
          <Line
            key={`interference-${index}`}
            points={[
              0, index * element.height * 0.2,
              element.width, index * element.height * 0.2 + 50,
            ]}
            stroke={bgData.secondaryColor || '#00E5FF'}
            strokeWidth={2}
            opacity={0.4}
            globalCompositeOperation="screen"
          />
        ))}
      </Group>
    );
  };

  // Render vaporwave background
  const renderVaporwave = () => {
    const gridLines = 15;
    const perspectiveHeight = element.height;

    return (
      <Group>
        {/* Sunset gradient */}
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fillLinearGradientStartPoint={{ x: element.width / 2, y: 0 }}
          fillLinearGradientEndPoint={{ x: element.width / 2, y: element.height }}
          fillLinearGradientColorStops={[
            0, '#FF6B6B',
            0.3, '#FF8E53',
            0.6, '#4ECDC4',
            1, bgData.primaryColor,
          ]}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {/* Perspective grid */}
        {Array.from({ length: gridLines }).map((_, index) => {
          const y = element.height * 0.5 + (index * perspectiveHeight) / gridLines;
          const width = (index / gridLines) * element.width * 2;
          const x = (element.width - width) / 2;

          return (
            <Line
              key={`vapor-${index}`}
              points={[
                x, y,
                x + width, y,
              ]}
              stroke={bgData.secondaryColor || '#00E5FF'}
              strokeWidth={2}
              opacity={0.6 - index * 0.03}
              globalCompositeOperation="screen"
            />
          );
        })}
      </Group>
    );
  };

  // Render scanlines background
  const renderScanlines = () => {
    const scanlineHeight = 3;
    const scanlines = Math.ceil(element.height / scanlineHeight);

    return (
      <Group>
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill={bgData.primaryColor}
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {Array.from({ length: scanlines }).map((_, index) => (
          <Rect
            key={index}
            x={0}
            y={index * scanlineHeight}
            width={element.width}
            height={scanlineHeight}
            fill="black"
            opacity={index % 2 === 0 ? 0.1 : 0}
            globalCompositeOperation="multiply"
            perfectDrawEnabled={false}
          />
        ))}
      </Group>
    );
  };

  // Render noise background (standalone, not as effect)
  const renderNoiseBackground = () => {
    const noiseCount = 2000;
    const noise = Array.from({ length: noiseCount }).map(() => ({
      x: Math.random() * element.width,
      y: Math.random() * element.height,
      width: Math.random() * 4 + 1,
      height: Math.random() * 4 + 1,
      color: Math.random() > 0.5
        ? bgData.primaryColor
        : (bgData.secondaryColor || '#00E5FF'),
    }));

    return (
      <Group>
        <Rect
          x={0}
          y={0}
          width={element.width}
          height={element.height}
          fill="#000000"
          opacity={bgData.opacity}
          perfectDrawEnabled={false}
        />
        {noise.map((rect, index) => (
          <Rect
            key={index}
            x={rect.x}
            y={rect.y}
            width={rect.width}
            height={rect.height}
            fill={rect.color}
            opacity={0.15}
            globalCompositeOperation="overlay"
          />
        ))}
      </Group>
    );
  };

  // Render pattern background
  const renderPattern = () => {
    switch (bgData.backgroundType) {
      case 'dots':
        return renderDotsPattern();
      case 'stripes':
        return renderStripesPattern();
      case 'grid':
        return renderGridPattern();
      default:
        return renderDotsPattern(); // Default to dots
    }
  };

  // Render geometric background
  const renderGeometric = () => {
    switch (bgData.backgroundType) {
      case 'circles':
        return renderCircles();
      case 'squares':
        return renderSquares();
      case 'triangles':
        return renderTriangles();
      default:
        return renderCircles(); // Default to circles
    }
  };

  // Render shadow effect
  const renderShadow = () => {
    if (!bgData.effects?.shadow) {
      return null;
    }

    return (
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        fill="black"
        opacity={0.3}
        offsetX={5}
        offsetY={5}
        blur={10}
      />
    );
  };

  // Render glow effect
  const renderGlow = () => {
    if (!bgData.effects?.glow) {
      return null;
    }

    return (
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        fill={bgData.primaryColor}
        opacity={0.5}
        blur={20}
        globalCompositeOperation="screen"
      />
    );
  };

  // Render blur effect
  const renderBlur = () => {
    if (!bgData.effects?.blur) {
      return null;
    }

    return (
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        fill={bgData.primaryColor}
        opacity={bgData.opacity}
        blur={5}
      />
    );
  };

  // Render noise effect
  const renderNoise = () => {
    if (!bgData.effects?.noise) {
      return null;
    }

    // Create noise using multiple small random rectangles
    const noiseCount = 1000;
    const noise = Array.from({ length: noiseCount }).map(() => ({
      x: Math.random() * element.width,
      y: Math.random() * element.height,
      width: Math.random() * 3 + 1,
      height: Math.random() * 3 + 1,
    }));

    return (
      <Group>
        {noise.map((rect, index) => (
          <Rect
            key={index}
            x={rect.x}
            y={rect.y}
            width={rect.width}
            height={rect.height}
            fill="white"
            opacity={0.05}
            globalCompositeOperation="overlay"
          />
        ))}
      </Group>
    );
  };

  // Determine which background type to render
  const renderBackground = () => {
    switch (bgData.backgroundType) {
      case 'solid':
        return renderSolid();
      case 'gradient':
        return renderGradient();
      case 'pattern':
        return renderPattern();
      case 'geometric':
        return renderGeometric();
      case 'glass-gradient':
        return renderGlassGradient();
      case 'cyber-grid':
        return renderCyberGrid();
      case 'gradient-mesh':
        return renderGradientMesh();
      case 'isometric-grid':
        return renderIsometricGrid();
      case 'holographic':
        return renderHolographic();
      case 'vaporwave':
        return renderVaporwave();
      case 'scanlines':
        return renderScanlines();
      case 'noise':
        return renderNoiseBackground();
      default:
        return renderSolid(); // Default to solid
    }
  };

  return (
    <BaseElement
      element={element}
      isSelected={isSelected}
      onSelect={onSelect}
      onTransform={onTransform}
      enableResize={enableResize}
      enableRotate={enableRotate}
      keepAspectRatio={keepAspectRatio}
    >
      <Group>
        {/* Render effects in layer order */}
        {renderBlur()}
        {renderNoise()}
        {renderGlow()}
        {renderShadow()}

        {/* Render background */}
        <Group>
          {renderBackground()}
        </Group>

        {/* Render additional effects on top */}
        {renderNoise()}
      </Group>
    </BaseElement>
  );
};