'use client';

import React, { useMemo } from 'react';
import { Text } from 'react-konva';
import { TextElementData } from '@/types/canvas-elements';

/**
 * StyledTextSegment - Interface for a text segment with styling
 */
interface StyledTextSegment {
  text: string;
  bold?: boolean;
  italic?: boolean;
  code?: boolean;
  strikethrough?: boolean;
  color?: string;
  font?: string;
}

/**
 * Parse inline styling from markdown-like syntax
 *
 * Supports:
 * - **text** for bold
 * - *text* for italic
 * - `text` for code
 * - ~~text~~ for strikethrough
 * - [color:text] for color
 * - [font:fontname] for font
 */
export function parseInlineStyles(text: string): StyledTextSegment[] {
  const segments: StyledTextSegment[] = [];

  // Remove all styling markers and extract segments
  let remaining = text;
  let currentSegment: StyledTextSegment = { text: '' };

  while (remaining.length > 0) {
    // Check for bold **text**
    if (remaining.startsWith('**')) {
      const end = remaining.indexOf('**', 2);
      if (end !== -1) {
        if (currentSegment.text) {
          segments.push(currentSegment);
          currentSegment = { text: '' };
        }
        segments.push({
          text: remaining.substring(2, end),
          bold: true,
        });
        remaining = remaining.substring(end + 2);
        continue;
      }
    }

    // Check for italic *text*
    if (remaining.startsWith('*') && !remaining.startsWith('**')) {
      const end = remaining.indexOf('*', 1);
      if (end !== -1) {
        if (currentSegment.text) {
          segments.push(currentSegment);
          currentSegment = { text: '' };
        }
        segments.push({
          text: remaining.substring(1, end),
          italic: true,
        });
        remaining = remaining.substring(end + 1);
        continue;
      }
    }

    // Check for code `text`
    if (remaining.startsWith('`')) {
      const end = remaining.indexOf('`', 1);
      if (end !== -1) {
        if (currentSegment.text) {
          segments.push(currentSegment);
          currentSegment = { text: '' };
        }
        segments.push({
          text: remaining.substring(1, end),
          code: true,
        });
        remaining = remaining.substring(end + 1);
        continue;
      }
    }

    // Check for strikethrough ~~text~~
    if (remaining.startsWith('~~')) {
      const end = remaining.indexOf('~~', 2);
      if (end !== -1) {
        if (currentSegment.text) {
          segments.push(currentSegment);
          currentSegment = { text: '' };
        }
        segments.push({
          text: remaining.substring(2, end),
          strikethrough: true,
        });
        remaining = remaining.substring(end + 2);
        continue;
      }
    }

    // Check for color [color:text]
    if (remaining.startsWith('[') && remaining.includes(':')) {
      const end = remaining.indexOf(']', 1);
      if (end !== -1) {
        const content = remaining.substring(1, end);
        const colonIndex = content.indexOf(':');
        if (colonIndex !== -1) {
          const type = content.substring(0, colonIndex);
          const value = content.substring(colonIndex + 1);

          if (type === 'color') {
            if (currentSegment.text) {
              segments.push(currentSegment);
              currentSegment = { text: '' };
            }
            segments.push({
              text: value,
              color: value,
            });
            remaining = remaining.substring(end + 1);
            continue;
          }

          if (type === 'font') {
            if (currentSegment.text) {
              segments.push(currentSegment);
              currentSegment = { text: '' };
            }
            segments.push({
              text: remaining.substring(end + 1, remaining.indexOf(']', end + 1) + 1),
              font: value,
            });
            remaining = remaining.substring(remaining.indexOf(']', end + 1) + 1);
            continue;
          }
        }
      }
    }

    // Add character to current segment
    currentSegment.text += remaining[0];
    remaining = remaining.substring(1);
  }

  // Add last segment if it has text
  if (currentSegment.text) {
    segments.push(currentSegment);
  }

  return segments;
}

/**
 * StyledTextRenderer - Renders text with inline styling
 *
 * This component parses markdown-like syntax and renders multiple
 * Text nodes with different styles to support rich text.
 */
interface StyledTextRendererProps {
  text: string;
  baseData: TextElementData;
  x: number;
  y: number;
  width: number;
  height: number;
  opacity: number;
}

export const StyledTextRenderer: React.FC<StyledTextRendererProps> = ({
  text,
  baseData,
  x,
  y,
  width,
  height,
  opacity,
}) => {
  const segments = useMemo(() => parseInlineStyles(text), [text]);

  return (
    <>
      {segments.map((segment, index) => {
        // Calculate font weight
        let fontWeight = baseData.fontWeight;
        if (segment.bold) {
          fontWeight = '700';
        }

        // Calculate font style
        let fontStyle = baseData.fontStyle || 'normal';
        if (segment.italic) {
          fontStyle = 'italic';
        }

        // Calculate font family
        let fontFamily = baseData.fontFamily;
        if (segment.font) {
          fontFamily = segment.font;
        }

        // Calculate color
        let fill = baseData.color;
        if (segment.color) {
          fill = segment.color;
        }

        // Calculate text decoration
        let textDecoration = baseData.textDecoration || 'none';
        if (segment.strikethrough) {
          textDecoration = 'line-through';
        }

        // For code, use monospace font
        if (segment.code) {
          fontFamily = 'Courier New, monospace';
        }

        return (
          <Text
            key={index}
            text={segment.text}
            x={x}
            y={y}
            width={width}
            height={height}
            fontSize={baseData.fontSize}
            fontFamily={fontFamily}
            fontStyle={fontStyle}
            fontWeight={fontWeight}
            fill={fill}
            align={baseData.alignment as 'left' | 'center' | 'right'}
            lineHeight={baseData.lineHeight}
            letterSpacing={baseData.letterSpacing || 0}
            textDecoration={textDecoration}
            opacity={opacity}
            perfectDrawEnabled={false}
          />
        );
      })}
    </>
  );
};