'use client';

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Text } from 'react-konva';
import Konva from 'konva';
import { BaseElement } from './BaseElement';
import { StyledTextRenderer } from './StyledTextRenderer';
import { CanvasElement, TextElementData } from '@/types/canvas-elements';

interface TextElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  onElementUpdate?: (elementId: string, updates: Partial<CanvasElement>) => void; // ✅ ADD - Callback for updates
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

/**
 * TextElement - Renders editable text in the canvas editor
 *
 * Supports:
 * - Headline, subtext, bullets, quote, attribution rendering
 * - Text editing via double-click
 * - Rich text styling (font, size, weight, color, alignment, etc.)
 * - Inline styling (bold, italic, code, strikethrough)
 */
export const TextElement: React.FC<TextElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  onElementUpdate, // ✅ ADD - Callback for updates
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  // ❌ REMOVE: updateElement from canvas store
  // const { updateElement } = useCanvasStore();
  const textRef = useRef<Konva.Text>(null);

  const textData = element.data as TextElementData;

  // Text editing state
  const [isEditing, setIsEditing] = useState(false);
  const [editText, setEditText] = useState(textData.content);
  const [textareaPosition, setTextareaPosition] = useState({ x: 0, y: 0 });

  /**
   * Handle double-click to enable text editing
   */
  const handleDoubleClick = useCallback((e: any) => {
    e.stopPropagation();
    setIsEditing(true);
    setEditText(textData.content);

    // Calculate textarea position
    const textNode = e.target as Konva.Text;
    const stage = textNode.getStage();
    const transform = textNode.getAbsoluteTransform().copy();
    transform.invert();

    const pos = stage?.getPointerPosition();
    if (pos) {
      const absolutePosition = textNode.getAbsolutePosition();
      const scale = textNode.getAbsoluteScale();

      setTextareaPosition({
        x: absolutePosition.x,
        y: absolutePosition.y,
      });
    }
  }, [textData.content]);

/**
 * Handle text editing completion
 */
const handleTextEditComplete = useCallback(() => {
  setIsEditing(false);

  if (editText !== textData.content) {
    // ✅ ADD: Use onElementUpdate callback instead of updateElement
    onElementUpdate?.(element.id, {
      data: {
        ...textData,
        content: editText,
      },
    });
  }
}, [editText, textData, element.id, onElementUpdate]);

  /**
   * Handle text editing cancel
   */
  const handleTextEditCancel = useCallback(() => {
    setIsEditing(false);
    setEditText(textData.content);
  }, [textData.content]);

  /**
   * Handle keyboard events during text editing
   */
  const handleTextEditKeyDown = useCallback((e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleTextEditComplete();
    } else if (e.key === 'Escape') {
      handleTextEditCancel();
    }
  }, [handleTextEditComplete, handleTextEditCancel]);

  /**
   * Process inline styling markers
   * Converts markdown-like syntax to styled text segments
   * Note: Konva Text doesn't support rich text natively,
   * so this is a placeholder for future implementation
   * using HTMLText or multiple Text nodes
   */
  const processInlineStyles = useCallback((text: string): string => {
    // For now, just return the text as-is
    // Future implementation will parse markdown and create styled segments
    return text;
  }, []);

  /**
   * Calculate text alignment for Konva
   */
  const getKonvaAlignment = useCallback((alignment: string): 'left' | 'center' | 'right' => {
    return alignment as 'left' | 'center' | 'right';
  }, []);

  /**
   * Calculate font style string
   */
  const getFontStyle = useCallback((data: TextElementData): string => {
    let fontStyle = data.fontStyle || 'normal';

    if (data.textDecoration === 'underline') {
      fontStyle += ' underline';
    } else if (data.textDecoration === 'line-through') {
      fontStyle += ' line-through';
    }

    return fontStyle;
  }, []);

  /**
   * Calculate font weight
   */
  const getFontWeight = useCallback((weight: string | number): number | string => {
    if (typeof weight === 'number') {
      return weight;
    }

    const weightMap: Record<string, number | string> = {
      '100': 100,
      '200': 200,
      '300': 300,
      '400': 400,
      '500': 500,
      '600': 600,
      '700': 700,
      '800': 800,
      '900': 900,
      'normal': 400,
      'bold': 700,
      'lighter': 300,
      'bolder': 800,
    };

    return weightMap[weight] || 400;
  }, []);

  /**
   * Render text editing overlay
   */
  useEffect(() => {
    if (isEditing && textRef.current) {
      const textarea = document.createElement('textarea');
      textarea.value = editText;

      // Style the textarea to match the text element
      const stage = textRef.current.getStage();
      if (!stage) return;

      const textNode = textRef.current;
      const textPosition = textNode.getAbsolutePosition();
      const stageBox = stage.container().getBoundingClientRect();

      textarea.style.position = 'absolute';
      textarea.style.top = `${textPosition.y + stageBox.top}px`;
      textarea.style.left = `${textPosition.x + stageBox.left}px`;
      textarea.style.width = `${element.width}px`;
      textarea.style.height = `${element.height}px`;
      textarea.style.fontSize = `${textData.fontSize}px`;
      textarea.style.fontFamily = textData.fontFamily;
      textarea.style.fontWeight = typeof textData.fontWeight === 'number'
        ? textData.fontWeight.toString()
        : textData.fontWeight;
      textarea.style.fontStyle = textData.fontStyle || 'normal';
      textarea.style.color = textData.color;
      textarea.style.textAlign = textData.alignment;
      textarea.style.lineHeight = textData.lineHeight.toString();
      textarea.style.padding = '0';
      textarea.style.margin = '0';
      textarea.style.border = '2px solid #00E5FF';
      textarea.style.outline = 'none';
      textarea.style.resize = 'none';
      textarea.style.overflow = 'hidden';
      textarea.style.background = 'rgba(0, 0, 0, 0.8)';
      textarea.style.zIndex = '9999';
      textarea.style.borderRadius = '4px';

      document.body.appendChild(textarea);
      textarea.focus();
      textarea.select();

      const handleBlur = () => {
        handleTextEditComplete();
        document.body.removeChild(textarea);
      };

      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          handleBlur();
        } else if (e.key === 'Escape') {
          handleTextEditCancel();
          document.body.removeChild(textarea);
        }
      };

      textarea.addEventListener('blur', handleBlur);
      textarea.addEventListener('keydown', handleKeyDown);

      return () => {
        if (document.body.contains(textarea)) {
          textarea.removeEventListener('blur', handleBlur);
          textarea.removeEventListener('keydown', handleKeyDown);
          document.body.removeChild(textarea);
        }
      };
    }
  }, [
    isEditing,
    editText,
    element.width,
    element.height,
    textData,
    handleTextEditComplete,
    handleTextEditCancel,
  ]);

  // Check if inline styling is enabled
  const hasInlineStyles = textData.inlineStyles && (
    textData.inlineStyles.bold ||
    textData.inlineStyles.italic ||
    textData.inlineStyles.code ||
    textData.inlineStyles.strikethrough
  );

  // Also check if text contains markdown-like syntax
  const hasMarkdownSyntax = /(\*\*.*?\*\*|\*.*?\*|`.*?`|~~.*?~~)/.test(textData.content);

  const shouldUseStyledRenderer = hasInlineStyles || hasMarkdownSyntax;

  return (
    <>
      <BaseElement
        element={element}
        isSelected={isSelected}
        onSelect={onSelect}
        onTransform={onTransform}
        enableResize={enableResize}
        enableRotate={enableRotate}
        keepAspectRatio={keepAspectRatio}
      >
        {shouldUseStyledRenderer ? (
          // Use StyledTextRenderer for rich text
          <StyledTextRenderer
            text={textData.content}
            baseData={textData}
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            opacity={element.opacity}
          />
        ) : (
          // Use simple Text for plain text
          <Text
            ref={textRef}
            text={textData.content}
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fontSize={textData.fontSize}
            fontFamily={textData.fontFamily}
            fontStyle={getFontStyle(textData)}
            fontWeight={getFontWeight(textData.fontWeight).toString()}
            fill={textData.color}
            align={getKonvaAlignment(textData.alignment)}
            lineHeight={textData.lineHeight}
            letterSpacing={textData.letterSpacing || 0}
            textDecoration={textData.textDecoration || 'none'}
            opacity={element.opacity}
            perfectDrawEnabled={false}
            listening={true}
            onDblClick={handleDoubleClick}
            onDblTap={handleDoubleClick}
          />
        )}
      </BaseElement>
    </>
  );
};