/**
 * Position Translation Module
 *
 * Provides bidirectional translation between DOM positioning (CSS flexbox/percentages)
 * and Canvas positioning (pixel coordinates).
 *
 * This module implements smart position detection to preserve positioning intent
 * through mode switches, ensuring that auto-layout elements stay auto-layout when
 * possible.
 */

import { SLIDE_WIDTH, SLIDE_HEIGHT } from '@/config/constants';
import { ElementPosition } from '@/types/slide-subtypes';

/**
 * Threshold for considering positions "close enough" to be the same
 * Used for smart position detection
 */
const POSITION_TOLERANCE = 20; // pixels

/**
 * Center position of the slide
 */
const SLIDE_CENTER_X = SLIDE_WIDTH / 2;
const SLIDE_CENTER_Y = SLIDE_HEIGHT / 2;

/**
 * Canvas element with metadata for position translation
 */
export interface CanvasElementPosition {
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
}

/**
 * Check if an element is at the center of the slide
 *
 * @param element - Canvas element position data
 * @returns True if element is centered
 */
export function isCenterPosition(element: CanvasElementPosition): boolean {
  // Calculate element center
  const elementCenterX = element.x + element.width / 2;
  const elementCenterY = element.y + element.height / 2;

  // Check if element center is close to slide center
  const isXCentered = Math.abs(elementCenterX - SLIDE_CENTER_X) <= POSITION_TOLERANCE;
  const isYCentered = Math.abs(elementCenterY - SLIDE_CENTER_Y) <= POSITION_TOLERANCE;

  return isXCentered && isYCentered;
}

/**
 * Check if an element is at the left edge of the slide
 *
 * @param element - Canvas element position data
 * @returns True if element is at left edge
 */
export function isLeftEdgePosition(element: CanvasElementPosition): boolean {
  return Math.abs(element.x) <= POSITION_TOLERANCE;
}

/**
 * Check if an element is at the right edge of the slide
 *
 * @param element - Canvas element position data
 * @returns True if element is at right edge
 */
export function isRightEdgePosition(element: CanvasElementPosition): boolean {
  return Math.abs((element.x + element.width) - SLIDE_WIDTH) <= POSITION_TOLERANCE;
}

/**
 * Check if an element is at the top edge of the slide
 *
 * @param element - Canvas element position data
 * @returns True if element is at top edge
 */
export function isTopEdgePosition(element: CanvasElementPosition): boolean {
  return Math.abs(element.y) <= POSITION_TOLERANCE;
}

/**
 * Check if an element is at the bottom edge of the slide
 *
 * @param element - Canvas element position data
 * @returns True if element is at bottom edge
 */
export function isBottomEdgePosition(element: CanvasElementPosition): boolean {
  return Math.abs((element.y + element.height) - SLIDE_HEIGHT) <= POSITION_TOLERANCE;
}

/**
 * Check if an element is at an edge position (left, right, top, or bottom)
 *
 * @param element - Canvas element position data
 * @returns True if element is at an edge
 */
export function isEdgePosition(element: CanvasElementPosition): boolean {
  return (
    isLeftEdgePosition(element) ||
    isRightEdgePosition(element) ||
    isTopEdgePosition(element) ||
    isBottomEdgePosition(element)
  );
}

/**
 * Detect the alignment of an element based on its position
 *
 * @param element - Canvas element position data
 * @returns Detected alignment
 */
export function detectAlignment(element: CanvasElementPosition): 'left' | 'center' | 'right' {
  const elementCenterX = element.x + element.width / 2;

  if (Math.abs(elementCenterX - SLIDE_CENTER_X) <= POSITION_TOLERANCE) {
    return 'center';
  } else if (Math.abs(element.x) <= POSITION_TOLERANCE) {
    return 'left';
  } else {
    return 'right';
  }
}

/**
 * Convert DOM position to Canvas pixel position
 *
 * @param position - DOM position (auto, absolute, or relative)
 * @param elementWidth - Element width in pixels
 * @param elementHeight - Element height in pixels
 * @param defaultY - Default Y position for auto layout
 * @returns Canvas position in pixels
 */
export function domToCanvasPosition(
  position: ElementPosition | undefined,
  elementWidth: number,
  elementHeight: number,
  defaultY: number = 200
): { x: number; y: number; _mode?: string; _alignment?: string } {
  // Default to auto layout
  if (!position || position.mode === 'auto') {
    const alignment = position?.alignment || 'center';

    let x: number;
    switch (alignment) {
      case 'left':
        x = 40; // Left margin
        break;
      case 'right':
        x = SLIDE_WIDTH - elementWidth - 40; // Right margin
        break;
      case 'center':
      default:
        x = SLIDE_CENTER_X - elementWidth / 2;
        break;
    }

    // Calculate Y position with margin if specified
    let y = defaultY;
    if (position?.marginTop) {
      y += position.marginTop;
    }

    return {
      x,
      y,
      _mode: 'auto',
      _alignment: alignment,
    };
  }

  // Absolute positioning
  if (position.mode === 'absolute') {
    const x = (position.x || 0) / 100 * SLIDE_WIDTH;
    const y = (position.y || 0) / 100 * SLIDE_HEIGHT;

    return {
      x,
      y,
      _mode: 'absolute',
      _alignment: position.alignment,
    };
  }

  // Relative positioning (treated as absolute with offset)
  if (position.mode === 'relative') {
    let x = (position.x || 0) / 100 * SLIDE_WIDTH;
    let y = (position.y || 0) / 100 * SLIDE_HEIGHT;

    // Apply margin offsets
    if (position.marginTop) {
      y += position.marginTop;
    }
    if (position.marginLeft) {
      x += position.marginLeft;
    }

    return {
      x,
      y,
      _mode: 'relative',
      _alignment: position.alignment,
    };
  }

  // Fallback to auto layout
  return {
    x: SLIDE_CENTER_X - elementWidth / 2,
    y: defaultY,
    _mode: 'auto',
    _alignment: 'center',
  };
}

/**
 * Convert Canvas pixel position to DOM position
 *
 * This function uses smart detection to preserve positioning intent:
 * - If element is at center, preserve as auto with center alignment
 * - If element is at edge, preserve as auto with edge alignment
 * - Otherwise, convert to absolute positioning
 *
 * @param element - Canvas element position data
 * @param originalPosition - Original DOM position (if available)
 * @returns DOM position
 */
export function canvasToDomPosition(
  element: CanvasElementPosition,
  originalPosition?: ElementPosition
): ElementPosition {
  // Check if we have original position metadata
  const originalMode = originalPosition?.mode || 'auto';

  // Smart detection: Try to preserve auto layout when possible
  if (originalMode === 'auto' && isCenterPosition(element)) {
    // Element is still centered, preserve auto layout
    return {
      mode: 'auto',
      alignment: 'center',
    };
  }

  if (originalMode === 'auto' && isEdgePosition(element)) {
    // Element is at edge, preserve auto layout with appropriate alignment
    let alignment: 'left' | 'center' | 'right' = 'center';

    if (isLeftEdgePosition(element)) {
      alignment = 'left';
    } else if (isRightEdgePosition(element)) {
      alignment = 'right';
    }

    // Calculate margin offset if moved from default position
    const defaultY = 200; // Default headline Y position
    const marginTop = element.y - defaultY;

    if (marginTop !== 0) {
      return {
        mode: 'auto',
        alignment,
        marginTop: marginTop > 0 ? marginTop : undefined,
        marginBottom: marginTop < 0 ? Math.abs(marginTop) : undefined,
      };
    }

    return {
      mode: 'auto',
      alignment,
    };
  }

  // Convert to absolute positioning
  const x = (element.x / SLIDE_WIDTH) * 100;
  const y = (element.y / SLIDE_HEIGHT) * 100;
  const width = (element.width / SLIDE_WIDTH) * 100;
  const height = (element.height / SLIDE_HEIGHT) * 100;

  return {
    mode: 'absolute',
    x: Math.round(x * 100) / 100, // Round to 2 decimal places
    y: Math.round(y * 100) / 100,
    width: Math.round(width * 100) / 100,
    height: Math.round(height * 100) / 100,
    rotation: element.rotation,
  };
}

/**
 * Get default Y position for different element types
 *
 * @param elementType - Type of element (headline, subtext, bullets, etc.)
 * @returns Default Y position in pixels
 */
export function getDefaultYPosition(elementType: string): number {
  const defaultPositions: Record<string, number> = {
    headline: 200,
    subtext: 350,
    bullets: 400,
    quote: 300,
    attribution: 500,
    image: 200,
  };

  return defaultPositions[elementType] || 200;
}

/**
 * Preserve rotation through position conversion
 *
 * @param rotation - Rotation in degrees
 * @returns Rotation value (0 if invalid)
 */
export function preserveRotation(rotation: number = 0): number {
  // Normalize rotation to 0-360 range
  let normalized = rotation % 360;
  if (normalized < 0) {
    normalized += 360;
  }

  return normalized;
}