'use client';

import React from 'react';
import { Group, Rect, Text, Line, Circle, Star } from 'react-konva';
import useImage from 'use-image';
import { BaseElement } from './BaseElement';
import { CanvasElement, DecoratorElementData, DecoratorType } from '@/types/canvas-elements';
import {
  DecoratorConfig,
  DEFAULT_DECORATOR_CONFIG,
  mergeDecoratorConfig,
  CornerAccent,
  BorderConfig,
  SlideNumberConfig,
  HashtagConfig,
  WatermarkConfig,
  LogoConfig,
  FrameConfig,
  AccentLineConfig,
} from '@/types/decorators';

// Constants
const SLIDE_WIDTH = 1080;
const SLIDE_HEIGHT = 1350;

interface DecoratorElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

/**
 * DecoratorElement - Renders decorators in the canvas editor
 *
 * Features:
 * - Slide numbers (decimal, roman, circle, square, minimal, pillar-branded)
 * - Borders (solid, dashed, dotted, double, gradient)
 * - Corner accents (bracket, line, dot, triangle, circle, cross, star, diamond, arrow, wave)
 * - Frame styles (photo, film, tech, minimal, none)
 * - Logo with blend modes
 * - Hashtags
 * - Watermarks with positioning
 * - Accent lines (top, bottom, left, right)
 * - Pillar labels
 * - Background effects (shadow, glow, blur, noise)
 */
export const DecoratorElement: React.FC<DecoratorElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  const decoData = element.data as DecoratorElementData;
  const config = decoData.config;

  /**
   * Render slide number
   */
  const renderSlideNumber = () => {
    const config = decoData.config.slideNumber as SlideNumberConfig;
    if (!config.enabled) return null;

    const position = config.position;
    const size = config.size || 48;
    const color = config.color || '#666666';

    // Calculate position based on position type
    let x = 0;
    let y = 0;
    let text = '1';

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60 - size * 2;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60 - size * 2;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60 - size * 2;
        y = SLIDE_HEIGHT - 60 - size * 2;
        break;
      default:
        x = SLIDE_WIDTH - 60 - size * 2;
        y = SLIDE_HEIGHT - 60 - size * 2;
    }

    // Format number based on style
    let formattedNumber = text;
    switch (config.style) {
      case 'decimal':
        formattedNumber = `${text}`;
        break;
      case 'roman':
        const romanNumerals = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII', 'XIII', 'XIV', 'XV', 'XVI', 'XVII', 'XVIII', 'XIX', 'XX'];
        formattedNumber = romanNumerals[(parseInt(text, 10) - 1) % 20] || 'I';
        break;
      case 'circle':
        const circleNumerals = ['①', '②', '③', '④', '⑤', '⑥', '⑦', '⑧', '⑧', '⑨', '⑩', '⑪', '⑫', '⑬', '⑭', '⑮', '⑯', '⑰', '⑱', '⑲'];
        formattedNumber = circleNumerals[(parseInt(text, 10) - 1) % 20] || '①';
        break;
      case 'square':
        const squareNumerals = ['⓵', '⓶', '⓷', '⓸', '⓹', '⓺', '⓻', '⓼', '⓽', '⓾', '⓿', 'ⓑ', 'ⓒ', 'ⓘ', 'ⓙ', 'ⓚ', 'ⓜ', 'ⓝ'];
        formattedNumber = squareNumerals[(parseInt(text, 10) - 1) % 20] || '⓵';
        break;
      case 'minimal':
        formattedNumber = `${text}`;
        break;
      case 'pillar-branded':
        formattedNumber = `${text}`;
        break;
    }

    // Background for number (if enabled)
    const background = config.showBackground ? (
      <Rect
        x={x - 4}
        y={y - 4}
        width={size * 2 + 8}
        height={size * 2 + 8}
        fill="#000000"
        opacity={0.5}
        cornerRadius={4}
      />
    ) : null;

    return (
      <Group>
        {background}
        <Text
          x={x}
          y={y}
          width={size * 2}
          height={size * 2}
          text={formattedNumber}
          fontSize={size}
          fontFamily={config.font || 'Inter'}
          fontWeight="600"
          fontStyle="italic"
          fill={color}
          align="center"
          verticalAlign="middle"
          opacity={1}
        />
      </Group>
    );
  };

  /**
   * Render border
   */
  const renderBorder = () => {
    const config = decoData.config.border as BorderConfig;
    if (!config.enabled) return null;

    const { style, thickness, position, color, offset, padding, cornerRadius } = config;
    const borderColor = color || '#666666';

    const borderStyle = style;
    const borderWidth = thickness || 2;

    // Calculate border dimensions based on position
    let x = 0;
    let y = 0;
    let width = SLIDE_WIDTH;
    let height = SLIDE_HEIGHT;

    switch (position) {
      case 'top':
        y = offset || 0;
        height = borderWidth;
        break;
      case 'bottom':
        y = SLIDE_HEIGHT - (offset || 0) - borderWidth;
        height = borderWidth;
        break;
      case 'left':
        x = offset || 0;
        width = borderWidth;
        break;
      case 'right':
        x = SLIDE_WIDTH - (offset || 0) - borderWidth;
        width = borderWidth;
        break;
      case 'corners':
        // Handled by renderCornerAccents
        return null;
      case 'top-bottom':
        y = offset || 0;
        height = SLIDE_HEIGHT - (offset || 0) - borderWidth * 2;
        break;
      case 'left-right':
        x = offset || 0;
        width = SLIDE_WIDTH - (offset || 0) - borderWidth * 2;
        break;
      case 'full':
      default:
        // Full border
        x = padding || 0;
        y = padding || 0;
        width = SLIDE_WIDTH - (padding || 0) * 2;
        height = SLIDE_HEIGHT - (padding || 0) * 2;
        break;
    }

    // Apply corner radius if full border
    const borderRadius = position === 'full' ? cornerRadius || 0 : 0;

    return (
      <Rect
        x={x}
        y={y}
        width={width}
        height={height}
        stroke={borderColor}
        strokeWidth={borderWidth}
        strokeDash={
          borderStyle === 'dashed' ? [8, 8] :
          borderStyle === 'dotted' ? [2, 4] :
          borderStyle === 'double' ? [6, 2] :
          []
        }
        cornerRadius={borderRadius}
        opacity={1}
        perfectDrawEnabled={false}
      />
    );
  };

  /**
   * Render corner accent
   */
  const renderCornerAccent = (corner: 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight') => {
    const cornerAccents = config.cornerAccents;
    if (!cornerAccents) return null;

    const accent = cornerAccents[corner];
    if (!accent) return null;

    const style = accent.style as CornerAccent['style'];
    const size = accent.size || 48;
    const color = accent.color || '#00E5FF';
    const thickness = accent.thickness || 8;
    const rotation = accent.rotation || 0;
    const offset = accent.offset || { x: 0, y: 0 };
    const secondaryColor = accent.secondaryColor;

    const cornerPositions = {
      topLeft: { x: 0, y: 0 },
      topRight: { x: SLIDE_WIDTH, y: 0 },
      bottomLeft: { x: 0, y: SLIDE_HEIGHT },
      bottomRight: { x: SLIDE_WIDTH, y: SLIDE_HEIGHT },
    };

    const pos = cornerPositions[corner];
    const x = pos.x + offset.x;
    const y = pos.y + offset.y;

    switch (style) {
      case 'bracket':
        // Draw bracket corner
        return (
          <Group x={x} y={y} rotation={rotation}>
            {/* Top line */}
            <Line
              x={0}
              y={0}
              width={size}
              height={thickness}
              stroke={color}
              strokeWidth={thickness}
              lineCap="round"
              opacity={1}
            />
            {/* Side line */}
            <Line
              x={0}
              y={0}
              width={thickness}
              height={size}
              stroke={color}
              strokeWidth={thickness}
              lineCap="round"
              opacity={1}
            />
          </Group>
        );

      case 'line':
        // Simple line accent
        return (
          <Line
            x={x}
            y={y}
            width={size}
            height={size}
            stroke={color}
            strokeWidth={thickness}
            lineCap="round"
            opacity={1}
          />
        );

      case 'dot':
        // Circle dot
        return (
          <Circle
            x={x}
            y={y}
            radius={size / 2}
            fill={color}
            opacity={1}
          />
        );

      case 'triangle':
        // Triangle
        const h = size * Math.sqrt(3) / 2;
        const halfSize = size / 2;
        return (
          <Line
            points={[
              x, y - h / 2,
              x - halfSize, y + h / 2,
              x + halfSize, y + h / 2,
            ]}
            closed
            fill={color}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'circle':
        // Circle
        return (
          <Circle
            x={x}
            y={y}
            radius={size / 2}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'cross':
        // Cross
        return (
          <Group>
            <Line
              x={x - size / 2}
              y={y - size / 2}
              width={size}
              height={size}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
            <Line
              x={x - size / 2}
              y={y - size / 2}
              width={size}
              height={size}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
          </Group>
        );

      case 'star':
        // Star
        return (
          <Star
            x={x}
            y={y}
            numPoints={5}
            innerRadius={size / 4}
            outerRadius={size / 2}
            fill={color}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'diamond':
        // Diamond
        const diamondH = size * 0.7;
        const halfW = size / 2;
        return (
          <Line
            points={[
              x, y - diamondH / 2,
              x + halfW, y,
              x, y + diamondH / 2,
              x - halfW, y,
            ]}
            closed
            fill={color}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'arrow':
        // Arrow
        const arrowH = size * 0.7;
        const arrowHalfW = size / 6;
        return (
          <Group>
            <Line
              x={x}
              y={y - arrowH / 2}
              width={size}
              height={arrowH}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
            <Line
              x={x + size}
              y={y}
              width={arrowHalfW}
              height={arrowHalfW}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
          </Group>
        );

      case 'wave':
        // Wave
        return (
          <Line
            x={x}
            y={y}
            width={size}
            height={size * 0.3}
            stroke={color}
            strokeWidth={thickness}
            opacity={1}
          />
        );

      default:
        return null;
    }
  };

  /**
   * Render accent line
   */
  const renderAccentLine = (position: 'top' | 'bottom' | 'left' | 'right') => {
    const accentLines = decoData.config.accentLines;
    if (!accentLines || !accentLines.enabled) return null;

    const { offset, thickness, length, color, gradient } = accentLines;
    const accentColor = color || '#00E5FF';

    const positions = {
      top: { x: 0, y: offset || 40 },
      bottom: { x: 0, y: SLIDE_HEIGHT - (offset || 40) },
      left: { x: offset || 40, y: 0 },
      right: { x: SLIDE_WIDTH - (offset || 40), y: 0 },
    };

    const pos = positions[position];

    return (
      <Line
        x={pos.x}
        y={pos.y}
        width={position === 'top' || position === 'bottom' ? SLIDE_WIDTH : length || 80}
        height={position === 'left' || position === 'right' ? SLIDE_HEIGHT : length || 80}
        stroke={accentColor}
        strokeWidth={thickness}
        opacity={1}
        dash={gradient ? [4, 4] : undefined}
      />
    );
  };

  /**
   * Render watermark
   */
  const renderWatermark = () => {
    const config = decoData.config.watermark as WatermarkConfig;
    if (!config.enabled || !config.text) return null;

    const x = (config.x / 100) * SLIDE_WIDTH;
    const y = (config.y / 100) * SLIDE_HEIGHT;
    const size = config.size || 120;
    const rotation = config.rotation || 0;
    const opacity = config.opacity ?? 0.3;

    return (
      <Group
        x={x}
        y={y}
        rotation={rotation}
        opacity={opacity}
      >
        <Text
          width={size * 2}
          height={size * 2}
          text={config.text}
          fontSize={size * 0.4}
          fontFamily="Arial"
          fill="#ffffff"
          align="center"
          verticalAlign="middle"
        />
      </Group>
    );
  };

  /**
   * Render logo
   */
  const renderLogo = () => {
    const config = decoData.config.logo as LogoConfig;
    if (!config.enabled || !config.imageUrl) return null;

    const position = config.position;
    const size = config.size || 80;
    const opacity = config.opacity ?? 1;
    const blendMode = (config.blendMode || 'normal') as GlobalCompositeOperation;

    let x = 0;
    let y = 0;

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
        break;
      default:
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
    }

    // Use-image hook for logo
    const [image] = useImage(config.imageUrl, 'anonymous');

    if (!image) {
      return null;
    }

    return (
      <Group
        x={x}
        y={y}
        width={size}
        height={size}
        offsetX={size / 2}
        offsetY={size / 2}
        opacity={opacity}
        globalCompositeOperation={blendMode}
      >
        <Rect
          width={size}
          height={size}
          fillPatternImage={image}
        />
      </Group>
    );
  };

  /**
   * Render hashtag
   */
  const renderHashtag = () => {
    const config = decoData.config.hashtag as HashtagConfig;
    if (!config.enabled || !config.text) return null;

    const position = config.position;
    const size = config.size || 32;
    const color = config.color || '#00E5FF';

    let x = 0;
    let y = 0;

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
        break;
      default:
        x = 60;
        y = 60;
    }

    // Background for hashtag (if enabled)
    const background = config.showBackground ? (
      <Rect
        x={x - 4}
        y={y - 4}
        width={size * 2 + 8}
        height={size * 2 + 8}
        fill="#000000"
        opacity={0.5}
        cornerRadius={4}
      />
    ) : null;

    return (
      <Group>
        {background}
        <Text
          x={x}
          y={y}
          text={`#${config.text}`}
          fontSize={size}
          fontFamily="Arial"
          fontWeight="600"
          fill={color}
          align="center"
          verticalAlign="middle"
        />
      </Group>
    );
  };

  /**
   * Render pillar label
   */
  const renderPillarLabel = () => {
    const config = decoData.config.pillarLabel;
    if (!config || !config.enabled) return null;

    const position = config.position;
    const size = config.size || 32;
    const color = '#00E5FF';

    let x = 0;
    let y = 0;

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
        break;
      default:
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
    }

    return (
      <Group>
        <Text
          x={x}
          y={y}
          text="Pillar"
          fontSize={size}
          fontFamily="Inter"
          fontWeight="700"
          fill={color}
          align="center"
          verticalAlign="middle"
        />
      </Group>
    );
  };

  /**
   * Render frame
   */
  const renderFrame = () => {
    const config = decoData.config.frame as FrameConfig;
    if (!config.enabled) return null;

    const { style, thickness, color, innerPadding } = config;
    const frameColor = color || '#666666';
    const padding = innerPadding || 8;

    let frameX = 0;
    let frameY = 0;
    let frameWidth = SLIDE_WIDTH;
    let frameHeight = SLIDE_HEIGHT;

    switch (style) {
      case 'photo':
        // Photo frame with white border and shadow
        frameX = padding;
        frameY = padding;
        frameWidth = SLIDE_WIDTH - padding * 2;
        frameHeight = SLIDE_HEIGHT - padding * 2;
        return (
          <Group>
            <Rect
              x={frameX}
              y={frameY}
              width={frameWidth}
              height={frameHeight}
              fill="white"
              stroke={frameColor}
              strokeWidth={thickness}
              shadowColor="rgba(0, 0, 0, 0.3)"
              shadowBlur={10}
              shadowOffsetY={5}
              opacity={1}
            />
          </Group>
        );

      case 'film':
        // Film strip frame at top
        frameY = 0;
        frameHeight = thickness || 8;
        return (
          <Rect
            x={0}
            y={frameY}
            width={SLIDE_WIDTH}
            height={frameHeight}
            fill="#000000"
            opacity={1}
            perfectDrawEnabled={false}
          />
        );

      case 'tech':
        // Tech/bracket frame
        return null; // Handled by corners

      case 'minimal':
        // Simple thin frame
        return (
          <Rect
            x={padding}
            y={padding}
            width={SLIDE_WIDTH - padding * 2}
            height={SLIDE_HEIGHT - padding * 2}
            stroke={frameColor}
            strokeWidth={thickness}
            opacity={1}
            perfectDrawEnabled={false}
          />
        );

      case 'none':
      default:
        return null;
    }
  };

  /**
   * Render background effects
   */
  const renderBackgroundEffects = () => {
    const effects = decoData.config.backgroundEffects;
    if (!effects) return null;

    return (
      <>
        {effects.shadow && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="black"
            opacity={0.3}
            offsetX={0}
            offsetY={0}
            blur={10}
          />
        )}
        {effects.glow && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="#00E5FF"
            opacity={0.3}
            blur={20}
            globalCompositeOperation="screen"
          />
        )}
        {effects.blur && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="transparent"
            opacity={1}
            blur={5}
          />
        )}
        {effects.noise && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="white"
            opacity={0.05}
            globalCompositeOperation="overlay"
            perfectDrawEnabled={false}
          />
        )}
      </>
    );
  };

  /**
   * Render decorator based on type
   */
  const renderDecorator = () => {
    switch (decoData.decoratorType) {
      case 'corner':
        return (
          <Group>
            {renderCornerAccent('topLeft')}
            {renderCornerAccent('topRight')}
            {renderCornerAccent('bottomLeft')}
            {renderCornerAccent('bottomRight')}
          </Group>
        );

      case 'border':
        return renderBorder();

      case 'frame':
        return renderFrame();

      case 'slideNumber':
        return renderSlideNumber();

      case 'logo':
        return renderLogo();

      case 'hashtag':
        return renderHashtag();

      case 'watermark':
        return renderWatermark();

      case 'pillarLabel':
        return renderPillarLabel();

      case 'line':
        return (
          <Group>
            {renderAccentLine('top')}
            {renderAccentLine('bottom')}
            {renderAccentLine('left')}
            {renderAccentLine('right')}
          </Group>
        );

      default:
        return null;
    }
  };

  return (
    <BaseElement
      element={element}
      isSelected={isSelected}
      onSelect={onSelect}
      onTransform={onTransform}
      enableResize={enableResize}
      enableRotate={enableRotate}
      keepAspectRatio={keepAspectRatio}
    >
      <Group>
        {/* Render background effects first */}
        {renderBackgroundEffects()}

        {/* Render decorator */}
        {renderDecorator()}
      </Group>
    </BaseElement>
  );
};